const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const cumbreVieja = ee.Geometry.Point([-17.84, 28.57]);
  const funchal = ee.Geometry.Point([-16.91, 32.65]);
  const date = '2021-10-18';

  // 2. Data Acquisition & Check
  const so2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_SO2')
    .filterDate(date, '2021-10-19')
    .select('SO2_column_number_density');

  const collectionSize = await so2Collection.size().getInfo();
  console.log(`Total SO2 images on ${date}: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log('No Sentinel-5P SO2 data available for this date.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Get mean SO2 for each location
  const so2Image = so2Collection.mean();

  // Check valid pixels at Cumbre Vieja
  const cumbreCount = await so2Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cumbreVieja,
    scale: 3000,
    maxPixels: 1e9
  }).get('SO2_column_number_density').getInfo();

  // Check valid pixels at Funchal
  const funchalCount = await so2Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: funchal,
    scale: 3000,
    maxPixels: 1e9
  }).get('SO2_column_number_density').getInfo();

  console.log(`Valid pixels - Cumbre Vieja: ${cumbreCount}, Funchal: ${funchalCount}`);

  if (cumbreCount === 0 || funchalCount === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Calculation - Get SO2 values
  const cumbreSO2 = await so2Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: cumbreVieja,
    scale: 3000,
    maxPixels: 1e9
  }).get('SO2_column_number_density').getInfo();

  const funchalSO2 = await so2Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: funchal,
    scale: 3000,
    maxPixels: 1e9
  }).get('SO2_column_number_density').getInfo();

  // 5. Validation & Final Answer
  if (cumbreSO2 === null || funchalSO2 === null || 
      isNaN(cumbreSO2) || isNaN(funchalSO2)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Cumbre Vieja SO2: ${cumbreSO2.toExponential(3)} mol/m²`);
  console.log(`Funchal SO2: ${funchalSO2.toExponential(3)} mol/m²`);
  console.log(`Difference: ${(cumbreSO2 - funchalSO2).toExponential(3)} mol/m²`);

  if (cumbreSO2 > funchalSO2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
